const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextInt() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        let res = 0;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            res = res * 10 + (input.charCodeAt(pos) - 48);
            pos++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;

    const ones = [0];
    for (let i = 1; i <= N; i++) {
        const val = nextInt();
        if (val === 1) {
            ones.push(i);
        }
    }
    ones.push(N + 1);

    let total = 0n;
    for (let i = 1; i < ones.length - 1; i++) {
        const leftChoices = BigInt(ones[i] - ones[i - 1]);
        const rightChoices = BigInt(ones[i + 1] - ones[i]);
        total += leftChoices * rightChoices;
    }

    console.log(total.toString());
}

main();
